// Reference implementation approved in the design canvas (DCLogic runtime).
// Port to src/components/ascii/*; do not import this file.
const COLS = 180, ROWS = 34;
const GRID = "";
const LEFT = " .:-=+*#%@";
const RIGHT = " .:;/<{}10";
const NOISE = "!<>-_/\[]{}=+*^?#01";

class Component extends DCLogic {
componentDidMount() {
  this._alive = true;
  this._boot();
}
componentWillUnmount() {
  this._alive = false;
  cancelAnimationFrame(this._raf);
  if (this._ro) this._ro.disconnect();
  if (this._io) this._io.disconnect();
}
_boot() {
  if (!this._alive) return;
  if (!this._cv) { this._raf = requestAnimationFrame(() => this._boot()); return; }
  const cv = this._cv;
  let seed = 7;
  this._rnd = () => { seed = (seed + 0x6D2B79F5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
  const n = COLS * ROWS, half = COLS / 2;
  const lvl = new Uint8Array(n), delay = new Float32Array(n);
  let tipL = null, tipR = null;
  for (let i = 0; i < n; i++) {
    lvl[i] = GRID.charCodeAt(i) - 48;
    const x = i % COLS, y = (i / COLS) | 0;
    delay[i] = (1 - Math.abs(x - half) / half) * 1300 + this._rnd() * 500;
    if (lvl[i] > 2) {
      if (x < half && (!tipL || x > tipL.x)) tipL = { x, y };
      if (x >= half && (!tipR || x < tipR.x)) tipR = { x, y };
    }
  }
  this._lvl = lvl; this._delay = delay; this._tipL = tipL; this._tipR = tipR;
  this._still = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
  this._t0 = null; this._visible = true;
  const resize = () => {
    if (!this._alive) return;
    const w = cv.clientWidth || (cv.parentNode && cv.parentNode.clientWidth) || 0;
    if (!w) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const cw = w / COLS, fs = cw / 0.6, ch = fs, h = Math.round(ch * ROWS);
    cv.style.height = h + 'px';
    cv.width = Math.round(w * dpr); cv.height = Math.round(h * dpr);
    const ctx = cv.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.font = fs.toFixed(2) + 'px "Geist Mono", ui-monospace, monospace';
    ctx.textBaseline = 'top';
    this._ctx = ctx; this._cw = cw; this._ch = ch; this._w = w; this._h = h;
    if (this._still) this._draw(1e9);
  };
  resize();
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(resize);
  if (window.ResizeObserver) { this._ro = new ResizeObserver(resize); this._ro.observe(cv.parentNode); }
  if (this._still) return;
  if (window.IntersectionObserver) {
    this._io = new IntersectionObserver((es) => {
      const e = es[es.length - 1];
      this._visible = e.isIntersecting;
      if (e.isIntersecting && this._t0 === null) this._t0 = performance.now();
    }, { threshold: 0.2 });
    this._io.observe(cv);
  } else {
    this._t0 = performance.now();
  }
  let last = 0;
  const loop = (now) => {
    if (!this._alive) return;
    this._raf = requestAnimationFrame(loop);
    if (!this._visible || this._t0 === null || now - last < 41) return;
    last = now;
    this._draw(now - this._t0);
  };
  this._raf = requestAnimationFrame(loop);
}
_draw(t) {
  const ctx = this._ctx;
  if (!ctx) return;
  const lvl = this._lvl, delay = this._delay, cw = this._cw, ch = this._ch, rnd = this._rnd;
  const half = COLS / 2;
  const still = t >= 1e9;
  ctx.clearRect(0, 0, this._w, this._h);
  for (let i = 0; i < lvl.length; i++) {
    const x = i % COLS, y = (i / COLS) | 0, L = lvl[i];
    if (!L) continue;
    const d = t - delay[i];
    if (d < 0) continue;
    const right = x >= half;
    let g = (right ? RIGHT : LEFT)[L];
    let a = 0.3 + (L / 9) * 0.7;
    if (d < 380) {
      g = NOISE[(rnd() * NOISE.length) | 0];
      a *= d / 380;
    } else if (!still) {
      a *= 0.85 + 0.15 * Math.sin(x * 0.09 - t * 0.0016 + y * 0.05);
      if (rnd() < (right ? 0.006 : 0.002)) {
        g = right ? (rnd() < 0.5 ? '0' : '1') : NOISE[(rnd() * NOISE.length) | 0];
      }
    }
    ctx.fillStyle = 'rgba(242,242,240,' + a.toFixed(3) + ')';
    ctx.fillText(g, x * cw, y * ch);
  }
  const A = this._tipL, B = this._tipR;
  if (!still && A && B && t > 2000) {
    const p = ((t - 2000) % 3600) / 1100;
    if (p <= 1.25) {
      const steps = Math.max(1, B.x - A.x - 2);
      for (let s = 1; s <= steps; s++) {
        const f = s / (steps + 1), k = p - f;
        if (k < 0 || k > 0.25) continue;
        const x = A.x + 1 + s, y = Math.round(A.y + (B.y - A.y) * f);
        ctx.fillStyle = 'rgba(242,242,240,' + (1 - k / 0.25).toFixed(3) + ')';
        ctx.fillText(k < 0.04 ? '>' : k < 0.12 ? '=' : '-', x * cw, y * ch);
      }
    }
  }
}
renderVals() {
  if (!this._handlers) {
    this._handlers = {
      canvasRef: (el) => { if (el) this._cv = el; },
    };
  }
  return this._handlers;
}
}
